package com.amit.colortodo;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.content.*;import android.content.res.ColorStateList;import android.view.*;import android.view.animation.*;import android.widget.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout list;ArrayList<TaskStore.Task> tasks;String size,style;final SimpleDateFormat df=new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault());
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(getColor(R.color.background));getWindow().setNavigationBarColor(getColor(R.color.background));setContentView(R.layout.activity_main);list=findViewById(R.id.list);size=TaskStore.pref(this,"size","default");style=TaskStore.pref(this,"style","card");findViewById(R.id.addFab).setOnClickListener(v->showAddDialog());findViewById(R.id.viewButton).setOnClickListener(v->showViewDialog());render();}
 @Override protected void onResume(){super.onResume();render();}
 void showAddDialog(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),dp(8),dp(20),dp(8));EditText title=input("Task title"),tag=input("Tag (e.g. Personal)"),notes=input("Notes (optional)");TextView due=inputLike("Select due date");final String[] date={""};due.setOnClickListener(v->{Calendar n=Calendar.getInstance();DatePickerDialog p=new DatePickerDialog(this,(x,y,m,d)->{Calendar s=Calendar.getInstance();s.set(y,m,d,0,0,0);date[0]=df.format(s.getTime());due.setText(new SimpleDateFormat("EEE, d MMM yyyy",Locale.getDefault()).format(s.getTime()));},n.get(1),n.get(2),n.get(5));p.show();});RadioGroup rg=new RadioGroup(this);rg.setOrientation(LinearLayout.HORIZONTAL);RadioButton h=radio("High"),m=radio("Medium"),l=radio("Low");h.setId(View.generateViewId());m.setId(View.generateViewId());l.setId(View.generateViewId());rg.addView(h);rg.addView(m);rg.addView(l);rg.check(m.getId());form.addView(title);form.addView(due);form.addView(tag);form.addView(notes);form.addView(rg);AlertDialog dialog=new AlertDialog.Builder(this,R.style.LayeredDialog).setTitle("New task").setView(form).setNegativeButton("CANCEL",null).setPositiveButton("ADD",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String s=title.getText().toString().trim();if(s.isEmpty()){title.setError("Add a title");return;}String p=h.isChecked()?"high":l.isChecked()?"low":"medium";tasks=TaskStore.load(this);tasks.add(new TaskStore.Task(System.currentTimeMillis(),s,p,false,date[0],tag.getText().toString().trim(),notes.getText().toString().trim()));TaskStore.save(this,tasks);dialog.dismiss();render();}));dialog.show();}
 void showViewDialog(){String[] ss={"Compact","Default","Expanded"},ls={"Card","List","Board"};LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(20),0,dp(20),dp(8));Spinner a=new Spinner(this),c=new Spinner(this);a.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,ss));c.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,ls));a.setSelection(size.equals("compact")?0:size.equals("expanded")?2:1);c.setSelection(style.equals("list")?1:style.equals("board")?2:0);b.addView(label("TASK SIZE"));b.addView(a);b.addView(label("LAYOUT"));b.addView(c);new AlertDialog.Builder(this,R.style.LayeredDialog).setTitle("View options").setView(b).setNegativeButton("CANCEL",null).setPositiveButton("APPLY",(d,w)->{size=a.getSelectedItem().toString().toLowerCase();style=c.getSelectedItem().toString().toLowerCase();TaskStore.setPref(this,"size",size);TaskStore.setPref(this,"style",style);render();}).show();}
 EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setTextColor(getColor(R.color.text_primary));e.setHintTextColor(getColor(R.color.text_muted));e.setSingleLine(true);e.setPadding(dp(16),0,dp(16),0);e.setBackgroundResource(R.drawable.input_bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.setMargins(0,0,0,dp(12));e.setLayoutParams(p);return e;}TextView inputLike(String h){TextView t=text(h,16,R.color.text_muted);t.setGravity(16);t.setPadding(dp(16),0,dp(16),0);t.setBackgroundResource(R.drawable.input_bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.setMargins(0,0,0,dp(12));t.setLayoutParams(p);return t;}RadioButton radio(String s){RadioButton r=new RadioButton(this);r.setText(s);r.setTextColor(getColor(R.color.text_primary));r.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{getColor(R.color.accent),getColor(R.color.text_muted)}));return r;}TextView label(String s){TextView t=text(s,11,R.color.text_muted);t.setTypeface(null,1);t.setLetterSpacing(.12f);t.setPadding(0,dp(16),0,dp(6));return t;}
 void render(){tasks=TaskStore.load(this);list.removeAllViews();tasks.sort(Comparator.comparingLong(TaskStore::weekStartFor).thenComparing(t->t.done));int open=0;for(TaskStore.Task t:tasks)if(!t.done)open++;((TextView)findViewById(R.id.taskCount)).setText(open==1?"1 ACTIVE":open+" ACTIVE");if(tasks.isEmpty()){LinearLayout e=new LinearLayout(this);e.setOrientation(LinearLayout.VERTICAL);e.setGravity(17);e.setPadding(dp(24),dp(110),dp(24),dp(48));TextView i=text("✓",32,R.color.accent);i.setGravity(17);e.addView(i);TextView h=text("Nothing pending",20,R.color.text_primary);h.setTypeface(null,1);h.setGravity(17);h.setPadding(0,dp(12),0,dp(6));e.addView(h);TextView s=text("Your space is clear. Add something when it matters.",13,R.color.text_muted);s.setGravity(17);e.addView(s);list.addView(e);return;}if(style.equals("board")){renderBoard();return;}LinkedHashMap<Long,List<TaskStore.Task>> g=new LinkedHashMap<>();for(TaskStore.Task t:tasks)g.computeIfAbsent(TaskStore.weekStartFor(t),k->new ArrayList<>()).add(t);for(Map.Entry<Long,List<TaskStore.Task>> e:g.entrySet())list.addView(week(e.getKey(),e.getValue()));}
 void renderBoard(){String[] ps={"high","medium","low"};String[] names={"HIGH PRIORITY","MEDIUM PRIORITY","LOW PRIORITY"};for(int i=0;i<ps.length;i++){ArrayList<TaskStore.Task> group=new ArrayList<>();for(TaskStore.Task t:tasks)if(t.priority.equals(ps[i]))group.add(t);if(group.isEmpty())continue;TextView h=text(names[i]+"   "+group.size(),11,R.color.text_secondary);h.setTypeface(null,1);h.setLetterSpacing(.1f);h.setPadding(dp(6),dp(14),0,dp(2));list.addView(h);for(TaskStore.Task t:group)list.addView(task(t));}}
 View week(long start,List<TaskStore.Task> ts){LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setPadding(0,0,0,dp(18));boolean ex=TaskStore.pref(this,"week_"+start,"true").equals("true");TextView h=text((ex?"⌄  ":"›  ")+TaskStore.weekLabel(start)+"   "+ts.size(),13,R.color.text_secondary);h.setTypeface(null,1);h.setGravity(16);h.setPadding(dp(18),dp(14),dp(18),dp(14));h.setBackgroundResource(R.drawable.week_header_bg);h.setElevation(dp(3));LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setVisibility(ex?0:8);for(TaskStore.Task t:ts)body.addView(task(t));h.setOnClickListener(v->{boolean show=body.getVisibility()!=0;body.setVisibility(show?0:8);h.setText((show?"⌄  ":"›  ")+TaskStore.weekLabel(start)+"   "+ts.size());TaskStore.setPref(this,"week_"+start,String.valueOf(show));});shell.addView(h);shell.addView(body);return shell;}
 View task(TaskStore.Task t){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(16);int p=size.equals("compact")?14:size.equals("expanded")?20:18;row.setPadding(dp(p),dp(p),dp(p),dp(p));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(style.equals("list")?dp(4):0,style.equals("list")?dp(4):dp(12),style.equals("list")?dp(4):0,0);row.setLayoutParams(lp);row.setBackground(priorityBg(t));row.setElevation(dp(style.equals("list")?2:10));CheckBox cb=new CheckBox(this);cb.setChecked(t.done);cb.setButtonTintList(ColorStateList.valueOf(getColor(R.color.card_text)));cb.setOnClickListener(v->completeAnimated(row,t));row.addView(cb,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);TextView title=text(t.text,size.equals("compact")?16:18,R.color.card_text);title.setTypeface(null,1);if(t.done){title.setPaintFlags(title.getPaintFlags()|Paint.STRIKE_THRU_TEXT_FLAG);title.setAlpha(.55f);}body.addView(title);if(!size.equals("compact")){LinearLayout meta=new LinearLayout(this);meta.setOrientation(LinearLayout.HORIZONTAL);meta.setPadding(0,dp(8),0,0);if(!t.due.isEmpty())meta.addView(chip(TaskStore.displayDate(t.due)));if(!t.tag.isEmpty())meta.addView(chip(t.tag));meta.addView(chip(t.priority.toUpperCase()));body.addView(meta);}if(size.equals("expanded")&&!t.notes.isEmpty()){TextView n=text(t.notes,13,R.color.card_text);n.setAlpha(.72f);n.setPadding(0,dp(10),0,0);n.setMaxLines(2);body.addView(n);}row.addView(body,new LinearLayout.LayoutParams(0,-2,1));TextView more=text("⋮",24,R.color.card_text);more.setAlpha(.75f);more.setGravity(17);row.addView(more,new LinearLayout.LayoutParams(dp(36),dp(44)));row.setOnTouchListener((v,e)->{if(e.getAction()==0){v.animate().scaleX(.975f).scaleY(.975f).translationZ(dp(-5)).setDuration(90).setInterpolator(new DecelerateInterpolator()).start();}else if(e.getAction()==1||e.getAction()==3){v.animate().scaleX(1f).scaleY(1f).translationZ(0).setDuration(240).setInterpolator(new OvershootInterpolator(.8f)).start();}return false;});final long[] last={0};row.setOnClickListener(v->{long n=System.currentTimeMillis();if(n-last[0]<350){completeAnimated(row,t);last[0]=0;}else last[0]=n;});View.OnLongClickListener del=v->{row.animate().scaleX(.9f).scaleY(.9f).alpha(0).translationX(dp(70)).setDuration(220).withEndAction(()->{tasks.removeIf(x->x.id==t.id);TaskStore.save(this,tasks);render();}).start();return true;};row.setOnLongClickListener(del);more.setOnLongClickListener(del);return row;}
 void completeAnimated(View v,TaskStore.Task t){v.animate().scaleX(1.025f).scaleY(1.025f).alpha(.82f).setDuration(120).withEndAction(()->{t.done=!t.done;TaskStore.save(this,tasks);v.animate().scaleX(.96f).scaleY(.96f).alpha(.35f).setDuration(180).withEndAction(this::render).start();}).start();}
 TextView chip(String s){TextView v=text(s,10,R.color.card_text);v.setTypeface(null,1);v.setAlpha(.88f);v.setBackgroundResource(R.drawable.chip_bg);v.setPadding(dp(9),dp(4),dp(9),dp(4));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(0,0,dp(7),0);v.setLayoutParams(p);return v;}
 Drawable priorityBg(TaskStore.Task t){int a,b;if(t.done){a=getColor(R.color.done_start);b=getColor(R.color.done_end);}else if(t.priority.equals("high")){a=getColor(R.color.high_start);b=getColor(R.color.high_end);}else if(t.priority.equals("low")){a=getColor(R.color.low_start);b=getColor(R.color.low_end);}else{a=getColor(R.color.medium_start);b=getColor(R.color.medium_end);}GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});g.setCornerRadius(dp(22));g.setStroke(dp(1),getColor(R.color.card_highlight));return g;}TextView text(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(getColor(c));return v;}int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}
}